        teams[away_team]['goals_for'] = teams[away_team].get('goals_for', 0) + away_goals
        teams[away_team]['goals_against'] = teams[away_team].get('goals_against', 0) + home_goals

        if home_goals > away_goals:
            teams[home_team]['points'] += 3
        elif home_goals < away_goals:
            teams[away_team]['points'] += 3
        else:
            teams[home_team]['points'] += 1
            teams[away_team]['points'] += 1

    for team in teams:
        teams[team]['goal_difference'] = teams[team]['goals_for'] - teams[team]['goals_against']

    sorted_teams = sorted(teams.items(), key=lambda x: (-x[1]['points'], -x[1]['goal_difference']))
